package com.example.authUtils;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;

/**
 * JWT Utility class for validating and extracting claims from JWT tokens.
 * 
 * JWTs are generated by NestJS. Spring Boot only validates signatures and
 * extracts claims from access tokens.
 * 
 * The JWT token contains (set by NestJS):
 * - sub (clientId for clients, employeeId for employees)
 * - username, jti, sid, token_use, actorType, iat, exp
 * - role for employee tokens only
 */
@Component
public class JwtUtil {
    private static final Logger logger = LoggerFactory.getLogger(JwtUtil.class);
    
    @Value("${jwt.secret}")
    private String jwtSecret;

    /**
     * Validate JWT token signature and expiration
     * 
     * @param token the JWT token
     * @return true if token is valid, false otherwise
     */
    public boolean validateToken(String token) {
        try {
            SecretKey key = signingKey();
            Jwts.parserBuilder()
                    .setSigningKey(key)
                    .build()
                    .parseClaimsJws(token);
            logger.debug("JWT token validated successfully");
            return true;
        } catch (SecurityException e) {
            logger.error("Invalid JWT signature: {}", e.getMessage());
        } catch (MalformedJwtException e) {
            logger.error("Invalid JWT token: {}", e.getMessage());
        } catch (ExpiredJwtException e) {
            logger.error("Expired JWT token: {}", e.getMessage());
        } catch (UnsupportedJwtException e) {
            logger.error("Unsupported JWT token: {}", e.getMessage());
        } catch (IllegalArgumentException e) {
            logger.error("JWT claims string is empty: {}", e.getMessage());
        }
        return false;
    }
    
    /**
     * Extract username from JWT token
     * 
     * @param token the JWT token
     * @return the username (subject)
     */
    public String getUsernameFromToken(String token) {
        return getClaimsFromToken(token).get("username", String.class);
    }
    
    /**
    * Extract the authenticated record ID from the numeric sub claim.
     */
    public Long getUserIdFromToken(String token) {
        String subject = getClaimsFromToken(token).getSubject();
        if (subject == null) {
            return null;
        }
        try {
            return Long.valueOf(subject);
        } catch (NumberFormatException exception) {
            return null;
        }
    }

    public String getActorTypeFromToken(String token) {
        return getClaimsFromToken(token).get("actorType", String.class);
    }

    public String getTokenUseFromToken(String token) {
        return getClaimsFromToken(token).get("token_use", String.class);
    }

    public String getTokenIdFromToken(String token) {
        return getClaimsFromToken(token).getId();
    }

    public String getSessionIdFromToken(String token) {
        return getClaimsFromToken(token).get("sid", String.class);
    }

    /**
     * Extract role from JWT token
     * Role is set by NestJS during token generation
     * 
     * @param token the JWT token
    * @return the employee role, or null for client tokens
     */
    public String getRoleFromToken(String token) {
        return getClaimsFromToken(token).get("role", String.class);
    }
    
    /**
     * Extract all claims from JWT token
     * 
     * @param token the JWT token
     * @return the Claims object
     */
    private Claims getClaimsFromToken(String token) {
        SecretKey key = signingKey();
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody();
    }

    private SecretKey signingKey() {
        return Keys.hmacShaKeyFor(jwtSecret.getBytes(StandardCharsets.UTF_8));
    }
}